def handle(args, state, ds):
    r = ds.next_action(args.get('scope'))
    if r.get('done'):
        return {'complete': True, 'message': 'Reconciliation queue is empty. All items processed.'}
    n = state.get('k', 0) + 1
    state['k'] = n
    return {'complete': False, 'item': n, 'action': r.get('action')}
